# hypothesis: A callback protocol with positional-only and keyword-only parameters accepts a matching class instance, rejects a plain function lacking the keyword, and nested generic Callable results keep their types.
from typing import Callable, Protocol, assert_type


def compose[A, B, C](f: Callable[[A], B], g: Callable[[B], C]) -> Callable[[A], C]:
    def inner(x: A) -> C:
        return g(f(x))
    return inner


def twice[T](f: Callable[[T], T]) -> Callable[[T], T]:
    def inner(x: T) -> T:
        return f(f(x))
    return inner


class Formatter(Protocol):
    def __call__(self, value: int, /, *, width: int = 0) -> str: ...


class Padder:
    def __call__(self, value: int, /, *, width: int = 0) -> str:
        return str(value).rjust(width)


def plain(value: int) -> str:
    return str(value)


def fmt_user(fmt: Formatter) -> str:
    return fmt(7, width=3)


def double(n: int) -> int:
    return n * 2


def try_plain() -> str:
    try:
        return fmt_user(plain)  # expect-error: plain has no width keyword
    except TypeError:
        return 'rejected'


doubled = compose(double, str)
assert_type(doubled, Callable[[int], str])
assert doubled(4) == '8'
quad = twice(twice(double))
assert_type(quad, Callable[[int], int])
assert quad(1) == 16
assert fmt_user(Padder()) == '  7'
assert try_plain() == 'rejected'
